//! First-start setup of a bundled Garage through its admin API (v2): a one-node layout,
//! the installation's access key (generated by install.sh), and the bucket. Safe to run at
//! every start: each step checks before it changes anything. Other S3 stores are set up by
//! their operators and skip this.

use serde_json::{Value, json};

pub struct Garage {
    http: reqwest::Client,
    admin: String,
    token: String,
}

pub struct Setup<'a> {
    pub key_id: &'a str,
    pub secret: &'a str,
    pub bucket: &'a str,
    /// Bytes this node offers; with one node it only has to be non-zero.
    pub capacity: u64,
}

impl Garage {
    pub fn new(admin_url: &str, token: &str) -> Self {
        Garage {
            http: reqwest::Client::new(),
            admin: admin_url.trim_end_matches('/').into(),
            token: token.into(),
        }
    }

    async fn call(
        &self,
        method: reqwest::Method,
        path: &str,
        body: Option<Value>,
    ) -> Result<(u16, Value), String> {
        let mut request = self
            .http
            .request(method, format!("{}{path}", self.admin))
            .bearer_auth(&self.token);
        if let Some(body) = body {
            request = request.json(&body);
        }
        let response = request.send().await.map_err(|e| format!("{path}: {e}"))?;
        let status = response.status().as_u16();
        Ok((status, response.json().await.unwrap_or(Value::Null)))
    }

    async fn ok(
        &self,
        method: reqwest::Method,
        path: &str,
        body: Option<Value>,
    ) -> Result<Value, String> {
        match self.call(method, path, body).await? {
            (200, v) => Ok(v),
            (status, v) => Err(format!("{path}: {status} {v}")),
        }
    }

    /// Everything the media service needs, created if missing.
    pub async fn setup(&self, s: &Setup<'_>) -> Result<Vec<String>, String> {
        use reqwest::Method;
        let mut done = Vec::new();

        let status = self.ok(Method::GET, "/v2/GetClusterStatus", None).await?;
        if status["layoutVersion"].as_u64().unwrap_or(0) == 0 {
            let node = status["nodes"][0]["id"]
                .as_str()
                .ok_or("GetClusterStatus: no node")?;
            self.ok(
                Method::POST,
                "/v2/UpdateClusterLayout",
                Some(json!({"roles": [{"id": node, "zone": "local", "capacity": s.capacity, "tags": []}]})),
            )
            .await?;
            self.ok(
                Method::POST,
                "/v2/ApplyClusterLayout",
                Some(json!({"version": 1})),
            )
            .await?;
            done.push(format!(
                "assigned the layout to node {}",
                &node[..16.min(node.len())]
            ));
        }

        let (status, _) = self
            .call(
                Method::GET,
                &format!("/v2/GetKeyInfo?id={}", s.key_id),
                None,
            )
            .await?;
        if status != 200 {
            self.ok(
                Method::POST,
                "/v2/ImportKey",
                Some(json!({"accessKeyId": s.key_id, "secretAccessKey": s.secret, "name": "xmsg-media"})),
            )
            .await?;
            done.push(format!("imported key {}", s.key_id));
        }

        let (status, bucket) = self
            .call(
                Method::GET,
                &format!("/v2/GetBucketInfo?globalAlias={}", s.bucket),
                None,
            )
            .await?;
        let bucket = if status == 200 {
            bucket
        } else {
            done.push(format!("created bucket {}", s.bucket));
            self.ok(
                Method::POST,
                "/v2/CreateBucket",
                Some(json!({"globalAlias": s.bucket})),
            )
            .await?
        };
        let bucket_id = bucket["id"].as_str().ok_or("bucket without an id")?;
        let allowed = bucket["keys"].as_array().is_some_and(|keys| {
            keys.iter().any(|k| {
                k["accessKeyId"] == s.key_id
                    && k["permissions"]["read"] == true
                    && k["permissions"]["write"] == true
            })
        });
        if !allowed {
            self.ok(
                Method::POST,
                "/v2/AllowBucketKey",
                Some(json!({"bucketId": bucket_id, "accessKeyId": s.key_id,
                            "permissions": {"read": true, "write": true, "owner": false}})),
            )
            .await?;
            done.push(format!(
                "gave key {} read and write on {}",
                s.key_id, s.bucket
            ));
        }
        Ok(done)
    }
}
